from collections import deque
def comps(g, bg):
    seen=set(); out=[]
    R,C=len(g),len(g[0])
    for i in range(R):
        for j in range(C):
            if g[i][j]!=bg and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); comp=[]
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for di in(-1,0,1):
                        for dj in(-1,0,1):
                            x,y=a+di,b+dj
                            if 0<=x<R and 0<=y<C and g[x][y]!=bg and (x,y) not in seen:
                                seen.add((x,y)); q.append((x,y))
                out.append(comp)
    return out
